INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Россия', '', 'DOMESTIC', NULL, TRUE, 'Поездка по России', 'Нужен паспорт РФ, для детей — свидетельство о рождении.', NULL, '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Абхазия', '', 'VISA_FREE', NULL, TRUE, 'Без визы, можно по паспорту РФ', 'Въезд по внутреннему паспорту РФ или загранпаспорту. Сбор на курорт оплачивается на месте.', NULL, '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Беларусь', '', 'VISA_FREE', 90, TRUE, 'Без визы до 90 дней, можно по паспорту РФ', 'Внутренний паспорт или загранпаспорт.', 'https://www.aviasales.ru/psgr/article/bzvz', '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Казахстан', '', 'VISA_FREE', 90, TRUE, 'Без визы до 90 дней в полугодии, можно по паспорту РФ', 'Внутренний паспорт или загранпаспорт, принимающая сторона оформляет уведомление о прибытии.', 'https://www.aviasales.ru/psgr/article/bzvz', '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Кыргызстан', '', 'VISA_FREE', 30, TRUE, 'Без визы, можно по паспорту РФ', 'Внутренний паспорт или загранпаспорт.', 'https://www.aviasales.ru/psgr/article/bzvz', '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Армения', '', 'VISA_FREE', 180, TRUE, 'Без визы до 180 дней в году, можно по паспорту РФ', 'При прилёте можно по внутреннему паспорту РФ. Свыше 30 дней нужна регистрация.', 'https://www.aviasales.ru/psgr/article/bzvz', '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Азербайджан', '', 'VISA_FREE', 90, FALSE, 'Без визы до 90 дней в полугодии', 'Нужен загранпаспорт. При пребывании дольше 15 дней — регистрация.', 'https://www.aviasales.ru/psgr/article/bzvz', '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Узбекистан', '', 'VISA_FREE', NULL, FALSE, 'Без визы, регистрация после 15 дней', 'Нужен загранпаспорт, при проживании в отеле регистрацию делает отель.', 'https://www.aviasales.ru/psgr/article/bzvz', '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Грузия', '', 'VISA_FREE', 365, FALSE, 'Без визы до 1 года', 'Загранпаспорт и медицинская страховка, действующая в Грузии.', 'https://www.aviasales.ru/psgr/article/bzvz', '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Турция', '', 'VISA_FREE', 60, FALSE, 'Без визы до 60 дней', 'Загранпаспорт, действительный не менее 120 дней на момент въезда.', 'https://www.aviasales.ru/psgr/article/bzvz', '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('ОАЭ', '', 'VISA_FREE', 90, FALSE, 'Без визы до 90 дней в полугодии', 'Загранпаспорт со сроком от 6 месяцев.', 'https://www.aviasales.ru/psgr/article/bzvz', '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Египет', '', 'VISA_ON_ARRIVAL', 30, FALSE, 'Виза по прилёте, 30 дней', 'Виза оформляется в аэропорту или онлайн, около 25–30 $. Загранпаспорт со сроком от 6 месяцев.', 'https://www.aviasales.ru/psgr/article/bzvz', '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Египет', 'Шарм-эль-Шейх', 'VISA_FREE', 15, FALSE, 'Без визы до 15 дней — штамп «Синай»', 'Бесплатный штамп при отдыхе только на Синае. Для экскурсий в Каир или Луксор — обычная виза по прилёте.', 'https://www.aviasales.ru/psgr/article/bzvz', '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Таиланд', '', 'VISA_FREE', 30, FALSE, 'Без визы до 30 дней', 'С 15 сентября 2026 года безвиз сокращён с 60 до 30 дней, продление ещё на 30 — в иммиграционном офисе. Нужна цифровая карта прибытия TDAC.', 'https://www.atorus.ru/article/tailand-vozvrashchaet-bezviz-na-30-dney-chto-izmenitsya-dlya-turistov-67986', '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Вьетнам', '', 'VISA_FREE', 45, FALSE, 'Без визы до 45 дней', 'Для поездок дольше — электронная виза до 90 дней.', 'https://www.aviasales.ru/psgr/article/bzvz', '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Китай', '', 'VISA_FREE', 30, FALSE, 'Без визы до 30 дней (до конца 2027 года)', 'Безвиз для граждан РФ продлён до 31 декабря 2027 года. Нужна электронная карта прибытия.', 'https://ria.ru/20260520/knr-2093487152.html', '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Индонезия', '', 'VISA_ON_ARRIVAL', 30, FALSE, 'Виза по прилёте или e-VoA, 30 дней', 'Оформляется в аэропорту или заранее онлайн (e-VoA), продлевается один раз ещё на 30 дней.', 'https://travel.persono.ru/bezvizovye-strany-dlya-rossiyan', '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Малайзия', '', 'VISA_FREE', 30, FALSE, 'Без визы до 30 дней', 'Нужна онлайн-карта прибытия MDAC.', 'https://travel.persono.ru/bezvizovye-strany-dlya-rossiyan', '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Филиппины', '', 'VISA_FREE', 30, FALSE, 'Без визы до 30 дней', 'Регистрация в системе eTravel перед вылетом.', 'https://travel.persono.ru/bezvizovye-strany-dlya-rossiyan', '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Мальдивы', '', 'VISA_FREE', 90, FALSE, 'Без визы, бесплатное разрешение по прилёте', 'Нужны обратные билеты, бронь отеля и онлайн-декларация IMUGA.', 'https://www.aviasales.ru/psgr/article/bzvz', '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Шри-Ланка', '', 'PRE_AUTHORIZATION', 30, FALSE, 'Электронное разрешение ETA, 30 дней', 'Разрешение оформляется онлайн до поездки.', 'https://www.aviasales.ru/psgr/article/bzvz', '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Камбоджа', '', 'VISA_ON_ARRIVAL', 30, FALSE, 'Виза по прилёте, 30 дней', 'Около 30 $, можно оформить и электронную визу заранее.', 'https://www.aviasales.ru/psgr/article/bzvz', '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Лаос', '', 'VISA_FREE', 30, FALSE, 'Без визы до 30 дней', 'Миграционная карта оформляется онлайн заранее.', 'https://www.aviasales.ru/psgr/article/bzvz', '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Южная Корея', '', 'PRE_AUTHORIZATION', 60, FALSE, 'Без визы до 60 дней с разрешением K-ETA', 'Электронное разрешение K-ETA обязательно для 18–64 лет. Не больше 90 дней за 180.', 'https://travel.persono.ru/bezvizovye-strany-dlya-rossiyan', '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Индия', '', 'E_VISA', NULL, FALSE, 'Нужна электронная виза e-Visa', 'Оформляется онлайн на официальном портале правительства Индии.', NULL, '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Сингапур', '', 'VISA_REQUIRED', NULL, FALSE, 'Нужна виза', 'Подаётся через уполномоченного агента или принимающую сторону.', 'https://travel.persono.ru/bezvizovye-strany-dlya-rossiyan', '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Япония', '', 'VISA_REQUIRED', NULL, FALSE, 'Нужна виза', 'Консульский сбор для граждан РФ нулевой, есть сервисный сбор визового центра.', 'https://travel.persono.ru/bezvizovye-strany-dlya-rossiyan', '2026-10-24');
INSERT INTO entry_rule (country, city, regime, max_days, internal_passport, summary, details, source_url, checked_on) VALUES ('Австралия', '', 'VISA_REQUIRED', NULL, FALSE, 'Нужна виза', 'Туристическая виза оформляется онлайн, с анкетой и проверкой.', 'https://travel.persono.ru/bezvizovye-strany-dlya-rossiyan', '2026-10-24');
